/**
 * generate-registry-index.mjs
 *
 * Rewrites open-sse/providers/registry/index.js from the directory listing.
 *
 * The file calls itself auto-generated but no generator shipped, so it was
 * maintained by hand and drifted: eleven providers (devin-cli, hcap, kimetsu,
 * mnn, nagaai, navyapi, trae, voidai, windsurf, zanityai, zukijourney) had an
 * import line but were missing from the exported array, which made them
 * invisible to the dashboard and to the gateway even though their files, their
 * logos and, for trae, a whole OAuth handler were all present.
 *
 * Run: node scripts/generate-registry-index.mjs [--check]
 *   --check exits non-zero instead of writing, for CI and the unit test.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REGISTRY_DIR = join(__dirname, "..", "open-sse", "providers", "registry");
const INDEX_FILE = join(REGISTRY_DIR, "index.js");

export function buildIndex(dir = REGISTRY_DIR) {
  const files = readdirSync(dir)
    .filter((f) => f.endsWith(".js") && f !== "index.js")
    .sort();

  const imports = files.map((f, i) => `import p${i} from "./${f}";`).join("\n");
  const list = files.map((_, i) => `  p${i},`).join("\n");

  return `// Auto-generated by scripts/generate-registry-index.mjs — do not edit by hand.
// Run: node scripts/generate-registry-index.mjs
${imports}

export default [
${list}
];
`;
}

// Only act when run directly. buildIndex is imported by the unit test, and a
// top-level process.exit here silently killed the whole test file: node --test
// reported it as one passing test while none of its assertions had run.
function main() {
  const check = process.argv.includes("--check");
  const next = buildIndex();
  const current = readFileSync(INDEX_FILE, "utf8");

  if (current === next) {
    console.log("registry index is up to date");
    return 0;
  }
  if (check) {
    console.error("registry index is STALE. Run: node scripts/generate-registry-index.mjs");
    return 1;
  }
  writeFileSync(INDEX_FILE, next, "utf8");
  console.log(`registry index rewritten: ${next.match(/^import p/gm).length} providers`);
  return 0;
}

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) {
  process.exit(main());
}
